window.AUTH=window.AUTH||{};window.AUTH["23-677"]={"d":"23-677","id":"2024/23-677","n":"Royal Canin U.S.A. v. Wullschleger","briefs":[{"k":"petitioner","label":"Brief of petitioners Royal Canin U.S.A. Inc., et al.","date":"2024-06-24","url":"https://www.supremecourt.gov/DocketPDF/23/23-677/315604/20240624163917953_Wullschleger%20Merits%20Brief%206-24-24%20Final.pdf","side":"pet","n":86},{"k":"respondent","label":"Brief of respondents Anastasia Wullschleger, et al.","date":"2024-08-05","url":"https://www.supremecourt.gov/DocketPDF/23/23-677/321623/20240805130820885_23-677BriefForRespondents.pdf","side":"res","n":74},{"k":"reply","label":"Reply of petitioners Royal Canin U.S.A. Inc., et al.","date":"2024-09-04","url":"https://www.supremecourt.gov/DocketPDF/23/23-677/324077/20240904132459806_Wullschleger%20Reply%209-4-24%20Final.pdf","side":"pet","n":61}],"opinion":"https://www.supremecourt.gov/opinions/24pdf/604us1r05_db8e.pdf","tr":true,"items":[{"t":"case","label":"Akin v. Ashland Chem. Co.","cite":"156 F.3d 1030","y":1998,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/156/1030/","by":{"0":"45"}},{"t":"case","label":"Anderson v. Allstate Ins. Co.","cite":"630 F.2d 677","y":1980,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/630/677/","by":{"0":"20"}},{"t":"case","label":"Armstrong v. Monex Int’l, Ltd.","cite":"413 F. Supp. 567","y":1976,"court":"N.D. Ill.","url":"https://www.courtlistener.com/c/F.%20Supp./413/567/","by":{"0":"21"}},{"t":"case","label":"Behlen v. Merrill Lynch","cite":"311 F.3d 1087","y":2002,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/311/1087/","by":{"0":"34"}},{"t":"case","label":"Bernstein v. Lind-Waldock & Co.","cite":"738 F.2d 179","y":1984,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/738/179/","by":{"0":"44, 45, 48"}},{"t":"case","label":"Boelens v. Redman Homes, Inc.","cite":"759 F.2d 504","y":1985,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/759/504/","by":{"0":"20, 31","2":"13"},"q":[{"src":"argument","who":"Ms. Wellington","text":"And if you look at cases like Boelens, which is a case that Justice Scalia cited in Rockwell from the Fifth Circuit, it very carefully explains the reasoning of why we treat these two circumstances differently."}]},{"t":"case","label":"Brough v. United Steelworkers of Am., AFLCIO","cite":"437 F.2d 748","y":1971,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/437/748/","by":{"0":"45"}},{"t":"case","label":"Brown v. E. States Corp.","cite":"181 F.2d 26","y":1950,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/181/26/","by":{"0":"21"}},{"t":"case","label":"Carlsbad Tech., Inc. v. HIF Bio, Inc.","cite":"556 U.S. 635","y":2009,"id":"2008/07-1437","sc":1,"by":{"0":"13, 33, 40","1":"39","2":"14"},"q":[{"src":"argument","who":"Ms. Wellington","text":"It also recognized it in cases like Carlsbad, where this Court was talking about Cohill remands and determined that they were not mandatory, that they were a matter of discretion for the district court."},{"src":"argument","who":"Ms. Wellington","text":"I think you also have to look at this Court's precedents, cases like International College of Surgeons, Rosado, Carlsbad, Osborn against Haley."},{"src":"argument","who":"Ms. Wellington","text":"There are also cases like Carlsbad, where this Court expressly asked, \"is a Cohill remand\" -- that's the phrase the Court used -- \"is a Cohill remand discretionary?\" I don't think this Court could answer the question yes without having, again, decided this question."}]},{"t":"case","label":"Carnegie-Mellon Univ. v. Cohill","cite":"484 U.S. 343","y":1988,"id":"1987/86-1021","sc":1,"by":{"0":"1, 10, 11, 16-19, 26, 27, 31, 35, 36, 41","1":"11, 40-42, 44, 46","2":"3, 10, 13, 14, 16, 17"},"q":[{"src":"brief","b":0,"text":"the scope of federal pendent jurisdiction.","cite":"484 U.S. at 349"},{"src":"brief","b":0,"text":"all federal-law claims are eliminated before trial,","cite":"484 U.S. at 350 n.7"},{"src":"brief","b":1,"text":"when the federal-law claims have dropped out of the lawsuit in its early stages and only state-law claims remain, the federal court should decline the exercise of jurisdiction.","cite":"484 U.S. at 350"},{"src":"brief","b":2,"text":"[F]orum manipulation concerns are legitimate and serious.","cite":"484 U.S. 343, 356 n.12"},{"src":"opinion","who":"Opinion of the Court (Justice Kagan)","text":"support[ ] giving a district court discretion to remand when the exercise of [supplemental] jurisdiction is inappropriate.","cite":"484 U. S., at 351"},{"src":"opinion","who":"Opinion of the Court (Justice Kagan)","text":"When the single federal-law claim in the action was eliminated at an early stage of the litigation, the District Court had a powerful reason to choose not to continue to exercise jurisdiction.","cite":"484 U. S., at 351"},{"src":"argument","who":"Ms. Wellington","text":"The second Justice Marshall confirmed that conclusion in Carnegie-Mellon against Cohill in 1988, and Justice Scalia concurred in Rockwell in 2007."}]},{"t":"case","label":"Ching v. Mitre Corp.","cite":"921 F.2d 11","y":1990,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/921/11/","by":{"0":"34"}},{"t":"case","label":"City of Chicago v. Int’l Coll. of Surgeons","cite":"522 U.S. 156","y":1997,"id":"1997/96-910","sc":1,"by":{"0":"22, 37","1":"21","2":"2, 3, 10, 14, 15"},"q":[{"src":"brief","b":0,"text":"exercise supplemental jurisdiction over the accompanying state law claims","cite":"522 U.S. at 165"}]},{"t":"case","label":"Clewis v. Medco Health Sols., Inc.","cite":"578 F. App’x 469","y":2014,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/578/469/","by":{"0":"34"}},{"t":"case","label":"Collura v. City of Philadelphia","cite":"590 F. App’x 180","y":2014,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/590/180/","by":{"0":"34"}},{"t":"case","label":"Comstock v. Morgan","cite":"165 F. Supp. 798","y":1958,"court":"W.D. Mo.","url":"https://www.courtlistener.com/c/F.%20Supp./165/798/","by":{"0":"21"}},{"t":"case","label":"Direct Transit Lines, Inc. v. Local Union No. 406, Int’l Brotherhood of Teamsters","cite":"199 F.2d 89","y":1952,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/199/89/","by":{"0":"21"}},{"t":"case","label":"Ellis v. Colonial Gas Co.","cite":"1983 WL 30335","y":1983,"court":"D. Mass. Nov. 21","by":{"0":"21"}},{"t":"case","label":"Exxon Mobil Corp. v. Allapattah Servs., Inc.","cite":"545 U.S. 546","y":2005,"id":"2004/04-70","sc":1,"by":{"0":"15, 24, 27, 28, 43","1":"32, 41, 42","2":"12"},"q":[{"src":"brief","b":0,"text":"in cases involving supplemental jurisdiction over additional claims between parties properly in federal court, the jurisdictional statutes should be read broadly.","cite":"545 U.S. 546, 553"},{"src":"brief","b":1,"text":"[T]o determine the scope of supplemental jurisdiction authorized by § 1367, then, we must examine the statute’s text in light of context, structure, and related statutory provisions.","cite":"545 U.S. 546, 558"},{"src":"argument","who":"Ms. Wellington","text":"And that's exactly the interpretive approach that this Court adopted in Exxon Mobil against Allapattah, where the Court was trying to figure out what does Section 1367 say about Rule 23 and plaintiffs in class actions."},{"src":"argument","who":"Ms. Wellington","text":"This Court in Exxon Mobil against Allapattah said really the key question is, is it in the statute? And -- and, certainly, amendments to the complaint is not in the statute."}]},{"t":"case","label":"Finley v. United States","cite":"490 U.S. 545","y":1989,"id":"1988/87-1973","sc":1,"by":{"0":"11, 15, 22, 46"},"q":[{"src":"brief","b":0,"text":"district court can consider whether the plaintiff has engaged in any manipulative tactics when it decides whether to remand a case.","cite":"490 U.S. 545"},{"src":"argument","who":"Ms. Wellington","text":"It was in response to Finley, where this Court took an extremely narrow view of pendent-claim and pendent-party jurisdiction, pendent-party jurisdiction in particular, and Congress said no, that's not what we want."},{"src":"argument","who":"Ms. Wellington","text":"We don't want Finley. We do want some limits. I think (b) tells you that (a) is so broadly written that if you don't have (b), that there would be concerns about diversity jurisdiction questions, Your Honor."},{"src":"argument","who":"Ms. Wellington","text":"In Finley, it adopted very broad language. And I think it would be very weird to think that Congress intended to abrogate Cohill silently without saying anything about it."}]},{"t":"case","label":"Fischer v. Star Co.","cite":"227 F. 955","y":1915,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F./227/955/","by":{"0":"21"}},{"t":"case","label":"Gale v. Chi. Title Ins. Co.","cite":"929 F.3d 74","y":2019,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/929/74/","by":{"0":"34, 43, 44"}},{"t":"case","label":"George v. McDonough","cite":"596 U.S. 740","y":2022,"id":"2021/21-234","sc":1,"by":{"0":"17, 27","2":"10"}},{"t":"case","label":"Gunn v. Minton","cite":"568 U.S. 251","y":2013,"id":"2012/11-1118","sc":1,"by":{"0":"5","1":"1, 2, 17, 19","2":"19, 20, 22"},"q":[{"src":"brief","b":1,"text":"canvas . . . that Jackson Pollock got to first.","cite":"568 U.S. 251, 258"},{"src":"brief","b":1,"text":"federal issue [that] is: (1) necessarily raised, (2) actually disputed, (3) substantial, and (4) capable of resolution in federal court without disrupting the federal-state balance approved by Congress.","cite":"568 U.S. at 258"},{"src":"brief","b":2,"text":"to the federal system as a whole.","cite":"568 U.S. at 260, 262"},{"src":"opinion","who":"Opinion of the Court (Justice Kagan)","text":"when federal law creates the cause of action asserted.","cite":"568 U. S. 251, 257"}]},{"t":"case","label":"Hammond v. Terminal R.R. Ass’n of St. Louis","cite":"848 F.2d 95","y":1988,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/848/95/","by":{"0":"20"}},{"t":"case","label":"Harless v. CSX Hotels, Inc.","cite":"389 F.3d 444","y":2004,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/389/444/","by":{"0":"34"}},{"t":"case","label":"Harper v. AutoAlliance Int’l, Inc.","cite":"392 F.3d 195","y":2004,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/392/195/","by":{"0":"34"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Kagan)","text":"[t]he existence of subject matter jurisdiction is determined by examining the complaint as it existed at the time of removal.","cite":"392 F. 3d 195, 210"}]},{"t":"case","label":"Hazel Bishop, Inc. v. Perfemme, Inc.","cite":"314 F.2d 399","y":1963,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/314/399/","by":{"0":"21"}},{"t":"case","label":"Henry v. Indep. Am. Sav. Ass’n","cite":"857 F.2d 995","y":1988,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/857/995/","by":{"0":"20"}},{"t":"case","label":"Highway Constr. Co. v. McClelland","cite":"15 F.2d 187","y":1926,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/15/187/","by":{"0":"8, 46"}},{"t":"case","label":"In Touch Concepts, Inc. v. Cellco P’ship","cite":"788 F.3d 98","y":2015,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/788/98/","by":{"0":"35"}},{"t":"case","label":"Jacks v. Torrington Co.","cite":"256 F. Supp. 282","y":1966,"court":"D.S.C.","url":"https://www.courtlistener.com/c/F.%20Supp./256/282/","by":{"0":"21"}},{"t":"case","label":"Johnson v. First Fed. Sav. & Loan Ass’n of Detroit","cite":"418 F. Supp. 1106","y":1976,"court":"E.D. Mich.","url":"https://www.courtlistener.com/c/F.%20Supp./418/1106/","by":{"0":"21"}},{"t":"case","label":"Kirby v. Am. Soda Fountain Co.","cite":"194 U.S. 141","y":1904,"id":"scdb/1903-134","sc":1,"by":{"0":"20"},"q":[{"src":"argument","who":"Ms. Wellington","text":"The Court extended that reasoning to removal actions in Kirby against American Soda in 1904. And in 1938, this Court held in St. Paul Mercury that if the plaintiff after removal amends his pleadings, this does not deprive the district court of jurisdiction because the defendant's statutory right to removal should not be subject to the plaintiff's caprice."}]},{"t":"case","label":"Koufakis v. Carvel","cite":"425 F.2d 892","y":1970,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/425/892/","by":{"0":"21"}},{"t":"case","label":"L.A. Draper & Son v. Wheelabrator-Frye, Inc.","cite":"735 F.2d 414","y":1984,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/735/414/","by":{"0":"26"}},{"t":"case","label":"Lorillard v. Pons","cite":"434 U.S. 575","y":1978,"id":"1977/76-1346","sc":1,"by":{"0":"42","2":"19"}},{"t":"case","label":"McLain v. Andersen Corp.","cite":"567 F.3d 956","y":2009,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/567/956/","by":{"0":"8, 34, 46"},"q":[{"src":"brief","b":0,"text":"discretion to exercise supplemental jurisdiction over remaining state-law claims.","cite":"567 F.3d at 965"}]},{"t":"case","label":"Moore v. Mars Petcare US, Inc.","cite":"966 F.3d 1007","y":2020,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/966/1007/","by":{"0":"4"}},{"t":"case","label":"Moore v. Mars Petcare US, Inc.","cite":"820 F. App’x 573","y":2020,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/820/573/","by":{"0":"4"}},{"t":"case","label":"Newman-Green, Inc. v. Alfonzo-Larrain","cite":"490 U.S. 826","y":1989,"id":"1988/88-774","sc":1,"by":{"0":"35"}},{"t":"case","label":"Ortiz-Bonilla v. Federación de Ajedrez de P.R., Inc.","cite":"734 F.3d 28","y":2013,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/734/28/","by":{"0":"34"}},{"t":"case","label":"Osborn v. Haley","cite":"549 U.S. 225","y":2007,"id":"2006/05-593","sc":1,"by":{"0":"32, 33","2":"7"},"q":[{"src":"brief","b":2,"text":"raised at the outset, the case would ‘aris[e] under’ federal law.","cite":"549 U.S. 225, 244-245"},{"src":"argument","who":"Ms. Wellington","text":"I think you also have to look at this Court's precedents, cases like International College of Surgeons, Rosado, Carlsbad, Osborn against Haley."},{"src":"argument","who":"Ms. Wellington","text":"Paul Mercury, Cohill, Rockwell, Gibbs, Carlsbad, Rosado, Powerex, Osborn against Haley, International College of Surgeons, and Wisconsin Department of Corrections."}]},{"t":"case","label":"Pintando v. Miami-Dade Hous. Agency","cite":"501 F.3d 1241","y":2007,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/501/1241/","by":{"0":"44"}},{"t":"case","label":"Powerex Corp. v. Reliant Energy Servs., Inc.","cite":"551 U.S. 224","y":2007,"id":"2006/05-85","sc":1,"by":{"0":"40"},"q":[{"src":"argument","who":"Ms. Wellington","text":"Paul Mercury, Cohill, Rockwell, Gibbs, Carlsbad, Rosado, Powerex, Osborn against Haley, International College of Surgeons, and Wisconsin Department of Corrections."}]},{"t":"case","label":"Price v. Highland Cmty. Bank","cite":"722 F. Supp. 454","y":1989,"court":"N.D. Ill.","url":"https://www.courtlistener.com/c/F.%20Supp./722/454/","by":{"0":"21"}},{"t":"case","label":"Prince v. Rescorp Realty","cite":"940 F.2d 1104","y":1991,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/940/1104/","by":{"0":"34"}},{"t":"case","label":"Rockwell Int’l Corp. v. United States","cite":"549 U.S. 457","y":2007,"id":"2006/05-1272","sc":1,"by":{"0":"3, 12, 13, 15, 30, 31, 43, 44","1":"36, 43, 47","2":"13, 16"},"q":[{"src":"brief","b":0,"text":"when a defendant removes a case to federal court based on the presence of a federal claim, an amendment eliminating the original basis for federal jurisdiction generally does not defeat jurisdiction.","cite":"549 U.S. 457, 474 n.6"},{"src":"brief","b":0,"text":"an amendment eliminating the original basis for federal jurisdiction generally does not defeat jurisdiction,","cite":"549 U.S. at 474 n.6"},{"src":"brief","b":1,"text":"when a plaintiff files a complaint in federal court and then voluntarily amends the complaint, courts look to the amended complaint to determine jurisdiction.","cite":"549 U.S. 457, 473-74"},{"src":"brief","b":1,"text":"[b]ut removal cases raise forum-manipulation concerns that simply do not exist when it is the plaintiff who chooses a federal forum and then pleads away jurisdiction through amendment.","cite":"549 U.S. at 474 n.6"},{"src":"argument","who":"Ms. Wellington","text":"The second Justice Marshall confirmed that conclusion in Carnegie-Mellon against Cohill in 1988, and Justice Scalia concurred in Rockwell in 2007."},{"src":"argument","who":"Ms. Wellington","text":"So this Court has treated these two situations differently, and Justice Scalia explained why in Rockwell. So there was a concern in Rockwell that when a plaintiff goes into federal court, pleads a federal question, and then immediately or subsequently drops it, that they're trying to plead their way into federal court."},{"src":"argument","who":"Ms. Wellington","text":"That is how we have asked this Court to read Rockwell. The U.S. Chamber of Commerce brief, you know --"}]},{"t":"case","label":"Rodriguez v. Comas","cite":"888 F.2d 899","y":1989,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/888/899/","by":{"0":"20"}},{"t":"case","label":"Rosado v. Wyman","cite":"397 U.S. 397","y":1970,"id":"1969/540","sc":1,"by":{"0":"10, 18, 25","1":"39","2":"2, 7, 13, 14"},"q":[{"src":"brief","b":0,"text":"the state claims should be dismissed as well.","cite":"397 U.S. 397"},{"src":"brief","b":0,"text":"jurisdiction over the primary claim at all stages as a prerequisite to resolution of the pendent claim.","cite":"397 U.S. at 405"},{"src":"brief","b":2,"text":"jurisdiction over the primary claim at all stages as a prerequisite to resolution of the pendent claim.","cite":"397 U.S. 397, 405"},{"src":"argument","who":"Ms. Wellington","text":"That's exactly what the Court held in Rosado, where the original federal claim became moot, and this Court said that -- that the three-judge district court could continue to go on and decide the ancillary claims even though it didn't have original jurisdiction because you don't have to have jurisdiction over the original federal claim through all proceedings."},{"src":"argument","who":"Ms. Wellington","text":"I think you also have to look at this Court's precedents, cases like International College of Surgeons, Rosado, Carlsbad, Osborn against Haley."},{"src":"argument","who":"Ms. Wellington","text":"There are other cases like International College of Surgeons and Rosado that, again, emphasize that this is a discretionary question. And I don't think this Court should just depart from all of that precedent here."}]},{"t":"case","label":"Sekhar v. United States","cite":"570 U.S. 729","y":2013,"id":"2012/12-357","sc":1,"by":{"0":"26"}},{"t":"case","label":"Solanics v. Republic Steel Corp.","cite":"34 F. Supp. 951","y":1940,"court":"N.D. Ohio","url":"https://www.courtlistener.com/c/F.%20Supp./34/951/","by":{"0":"21"}},{"t":"case","label":"S. Pac. Co. v. Haight","cite":"126 F.2d 900","y":1942,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/126/900/","by":{"0":"21"}},{"t":"case","label":"Sparta Surgical Corp. v. Nat’l Ass’n of Sec. Dealers, Inc.","cite":"159 F.3d 1209","y":1998,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/159/1209/","by":{"0":"34"}},{"t":"case","label":"Spear Mktg., Inc. v. BancorpSouth Bank","cite":"791 F.3d 586","y":2015,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/791/586/","by":{"0":"41"}},{"t":"case","label":"St. Paul Mercury Indem. Co. v. Red Cab Co.","cite":"303 U.S. 283","y":1938,"id":"scdb/1937-104","sc":1,"by":{"0":"2, 10, 15, 20, 31, 40, 43","1":"37","2":"8, 9, 12, 13"},"q":[{"src":"brief","b":0,"text":"deprive the district court of jurisdiction.","cite":"303 U.S. at 292"},{"src":"brief","b":0,"text":"does not deprive the district court of jurisdiction,","cite":"303 U.S. at 292"},{"src":"argument","who":"Ms. Wellington","text":"Paul Mercury that if the plaintiff after removal amends his pleadings, this does not deprive the district court of jurisdiction because the defendant's statutory right to removal should not be subject to the plaintiff's caprice."},{"src":"argument","who":"Justice Sotomayor","text":"Paul, and it agreed with the Court. It disagreed with the Court on pendent and supplemental jurisdiction, and it wrote a statute to address that."},{"src":"argument","who":"Ms. Wellington","text":"So this Court explained in St. Paul Mercury that once you've removed to federal court, there is a removal statute and the defendants have a right to remove."}]},{"t":"case","label":"Taggart v. Lorenzen","cite":"587 U.S. 554","y":2019,"id":"2018/18-489","sc":1,"by":{"0":"2, 26","2":"9, 10"},"q":[{"src":"brief","b":0,"text":"When a statutory term is obviously transplanted from another legal source, it brings the old soil with it.","cite":"587 U.S. at 560"},{"src":"argument","who":"Justice Barrett","text":"So you cite Taggart and the old soil principle, but what are you attaching it to as opposed to just some sort of, like, free-floating, everyone thought we could do this?"}]},{"t":"case","label":"Taylor v. First of Am. Bank-Wayne","cite":"973 F.2d 1284","y":1992,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/973/1284/","by":{"0":"34"}},{"t":"case","label":"United Mine Workers of Am. v. Gibbs","cite":"383 U.S. 715","y":1966,"id":"1965/243","sc":1,"by":{"0":"10, 17, 18, 26, 42","1":"31, 38","2":"5, 14-17"},"q":[{"src":"brief","b":0,"text":"that the entire action before the court comprises but one constitutional ‘case.’","cite":"383 U.S. at 725"},{"src":"brief","b":0,"text":"entire action before the court comprises but one constitutional ‘case.’","cite":"383 U.S. at 726"},{"src":"brief","b":2,"text":"judicial economy, convenience and fairness to litigants.","cite":"383 U.S. at 726"}]},{"t":"case","label":"United States v. Zima","cite":"766 F.2d 1153","y":1985,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/766/1153/","by":{"0":"26"}},{"t":"case","label":"Wellness Cmty.-Nat’l v. Wellness House","cite":"70 F.3d 46","y":1995,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/70/46/","by":{"0":"31"}},{"t":"case","label":"Westmoreland Hosp. Ass’n v. Blue Cross of W. Pa.","cite":"605 F.2d 119","y":1979,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/605/119/","by":{"0":"21"}},{"t":"case","label":"Wis. Dep’t of Corr. v. Schacht","cite":"524 U.S. 381","y":1998,"id":"1997/97-461","sc":1,"by":{"0":"40"}},{"t":"case","label":"Xactron Mgmt. Ltd. v. Kreepy Krauly U.S.A., Inc.","cite":"696 F. Supp. 1465","y":1988,"court":"S.D. Fla.","url":"https://www.courtlistener.com/c/F.%20Supp./696/1465/","by":{"0":"21"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"3"}},{"t":"usc","label":"28 U.S.C. § 1331","url":"https://www.law.cornell.edu/uscode/text/28/1331","stext":{"head":"§1331. Federal question","paras":[[0,"The district courts shall have original jurisdiction of all civil actions arising under the Constitution, laws, or treaties of the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1331?type=usc&year=mostrecent&link-type=html"},"by":{"0":"3","1":"10, 12, 21, 34"},"q":[{"src":"brief","b":1,"text":"original jurisdiction of all civil actions arising under the Constitution, laws, or treaties of the United States.","cite":"28 U.S.C. § 1331"},{"src":"brief","b":1,"text":"The district courts shall have original jurisdiction of all civil actions arising under the Constitution, laws, or treaties of the United States.","cite":"28 U.S.C. § 1331"}]},{"t":"usc","label":"28 U.S.C. § 1332","url":"https://www.law.cornell.edu/uscode/text/28/1332","subs":["(a)","(a)(1)"],"stext":{"head":"§1332. Diversity of citizenship; amount in controversy; costs","paras":[[0,"(a) The district courts shall have original jurisdiction of all civil actions where the matter in controversy exceeds the sum or value of $75,000, exclusive of interest and costs, and is between—"],[1,"(1) citizens of different States;"],[1,"(2) citizens of a State and citizens or subjects of a foreign state, except that the district courts shall not have original jurisdiction under this subsection of an action between citizens of a State and citizens or subjects of a foreign state who are lawfully admitted for permanent residence in the United States and are domiciled in the same State;"],[1,"(3) citizens of different States and in which citizens or subjects of a foreign state are additional parties; and"],[1,"(4) a foreign state, defined in section 1603(a) of this title, as plaintiff and citizens of a State or of different States."],[0,"(b) Except when express provision therefor is otherwise made in a statute of the United States, where the plaintiff who files the case originally in the Federal courts is finally adjudged to be entitled to recover less than the sum or value of $75,000, computed without regard to any setoff or counterclaim to which the defendant may be adjudged to be entitled, and exclusive of interest and costs, the district court may deny costs to the plaintiff and, in addition, may impose costs on the plaintiff."],[0,"(c) For the purposes of this section and section 1441 of this title—"],[1,"(1) a corporation shall be deemed to be a citizen of every State and foreign state by which it has been incorporated and of the State or foreign state where it has its principal place of business, except that in any direct action against the insurer of a policy or contract of liability insurance, whether incorporated or unincorporated, to which action the insured is not joined as a party-defendant, such insurer shall be deemed a citizen of—"],[2,"(A) every State and foreign state of which the insured is a citizen;"],[2,"(B) every State and foreign state by which the insurer has been incorporated; and"],[2,"(C) the State or foreign state where the insurer has its principal place of business; and"],[1,"(2) the legal representative of the estate of a decedent shall be deemed to be a citizen only of the same State as the decedent, and the legal representative of an infant or incompetent shall be deemed to be a citizen only of the same State as the infant or incompetent."],[0,"(d)(1) In this subsection—"],[1,"(A) the term \"class\" means all of the class members in a class action;"],[1,"(B) the term \"class action\" means any civil action filed under rule 23 of the Federal Rules of Civil Procedure or similar State statute or rule of judicial procedure authorizing an action to be brought by 1 or more representative persons as a class action;"],[1,"(C) the term \"class certification order\" means an order issued by a court approving the treatment of some or all aspects of a civil action as a class action; and"],[1,"(D) the term \"class members\" means the persons (named or unnamed) who fall within the definition of the proposed or certified class in a class action."],[0,"(2) The district courts shall have original jurisdiction of any civil action in which the matter in controversy exceeds the sum or value of $5,000,000, exclusive of interest and costs, and is a class action in which—"],[1,"(A) any member of a class of plaintiffs is a citizen of a State different from any defendant;"],[1,"(B) any member of a class of plaintiffs is a foreign state or a citizen or subject of a foreign state and any defendant is a citizen of a State; or"],[1,"(C) any member of a class of plaintiffs is a citizen of a State and any defendant is a foreign state or a citizen or subject of a foreign state."],[0,"(3) A district court may, in the interests of justice and looking at the totality of the circumstances, decline to exercise jurisdiction under paragraph (2) over a class action in which greater than one-third but less than two-thirds of the members of all proposed plaintiff classes in the aggregate and the primary defendants are citizens of the State in which the action was originally filed based on consideration of—"],[1,"(A) whether the claims asserted involve matters of national or interstate interest;"],[1,"(B) whether the claims asserted will be governed by laws of the State in which the action was originally filed or by the laws of other States;"],[1,"(C) whether the class action has been pleaded in a manner that seeks to avoid Federal jurisdiction;"],[1,"(D) whether the action was brought in a forum with a distinct nexus with the class members, the alleged harm, or the defendants;"],[1,"(E) whether the number of citizens of the State in which the action was originally filed in all proposed plaintiff classes in the aggregate is substantially larger than the number of citizens from any other State, and the citizenship of the other members of the proposed class is dispersed among a substantial number of States; and"],[1,"(F) whether, during the 3-year period preceding the filing of that class action, 1 or more other class actions asserting the same or similar claims on behalf of the same or other persons have been filed."],[0,"(4) A district court shall decline to exercise jurisdiction under paragraph (2)—"],[1,"(A)(i) over a class action in which—"],[2,"(I) greater than two-thirds of the members of all proposed plaintiff classes in the aggregate are citizens of the State in which the action was originally filed;"],[2,"(II) at least 1 defendant is a defendant—"],[3,"(aa) from whom significant relief is sought by members of the plaintiff class;"],[3,"(bb) whose alleged conduct forms a significant basis for the claims asserted by the proposed plaintiff class; and"],[3,"(cc) who is a citizen of the State in which the action was originally filed; and"],[2,"(III) principal injuries resulting from the alleged conduct or any related conduct of each defendant were incurred in the State in which the action was originally filed; and"],[1,"(ii) during the 3-year period preceding the filing of that class action, no other class action has been filed asserting the same or similar factual allegations against any of the defendants on behalf of the same or other persons; or"],[1,"(B) two-thirds or more of the members of all proposed plaintiff classes in the aggregate, and the primary defendants, are citizens of the State in which the action was originally filed."],[0,"(5) Paragraphs (2) through (4) shall not apply to any class action in which—"],[1,"(A) the primary defendants are States, State officials, or other governmental entities against whom the district court may be foreclosed from ordering relief; or"],[1,"(B) the number of members of all proposed plaintiff classes in the aggregate is less than 100."],[0,"(6) In any class action, the claims of the individual class members shall be aggregated to determine whether the matter in controversy exceeds the sum or value of $5,000,000, exclusive of interest and costs."],[0,"(7) Citizenship of the members of the proposed plaintiff classes shall be determined for purposes of paragraphs (2) through (6) as of the date of filing of the complaint or amended complaint, or, if the case stated by the initial pleading is not subject to Federal jurisdiction, as of the date of service by plaintiffs of an amended pleading, motion, or other paper, indicating the existence of Federal jurisdiction."],[0,"(8) This subsection shall apply to any class action before or after the entry of a class certification order by the court with respect to that action."],[0,"(9) Paragraph (2) shall not apply to any class action that solely involves a claim—"],[1,"(A) concerning a covered security as defined under 16(f)(3) 1 of the Securities Act of 1933 (15 U.S.C. 78p(f)(3) 2) and section 28(f)(5)(E) of the Securities Exchange Act of 1934 (15 U.S.C. 78bb(f)(5)(E));"],[1,"(B) that relates to the internal affairs or governance of a corporation or other form of business enterprise and that arises under or by virtue of the laws of the State in which such corporation or business enterprise is incorporated or organized; or"],[1,"(C) that relates to the rights, duties (including fiduciary duties), and obligations relating to or created by or pursuant to any security (as defined under section 2(a)(1) of the Securities Act of 1933 (15 U.S.C. 77b(a)(1)) and the regulations issued thereunder)."],[0,"(10) For purposes of this subsection and section 1453, an unincorporated association shall be deemed to be a citizen of the State where it has its principal place of business and the State under whose laws it is organized."],[0,"(11)(A) For purposes of this subsection and section 1453, a mass action shall be deemed to be a class action removable under paragraphs (2) through (10) if it otherwise meets the provisions of those paragraphs."],[0,"(B)(i) As used in subparagraph (A), the term \"mass action\" means any civil action (except a civil action within the scope of section 1711(2)) in which monetary relief claims of 100 or more persons are proposed to be tried jointly on the ground that the plaintiffs' claims involve common questions of law or fact, except that jurisdiction shall exist only over those plaintiffs whose claims in a mass action satisfy the jurisdictional amount requirements under subsection (a)."],[0,"(ii) As used in subparagraph (A), the term \"mass action\" shall not include any civil action in which—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1332?type=usc&year=mostrecent&link-type=html"},"by":{"0":"3","1":"10, 34","2":"7, 7"},"q":[{"src":"brief","b":1,"text":"civil actions where the matter . . . is between—(1) citizens of different states.","cite":"28 U.S.C. § 1332(a)"},{"src":"brief","b":2,"text":"civil actions where the matter * * * is between * * * citizens of different States.","cite":"28 U.S.C. § 1332(a)(1)"}]},{"t":"usc","label":"28 U.S.C. § 1367","url":"https://www.law.cornell.edu/uscode/text/28/1367","subs":["(a)","(b)","(c)","(c)(2)","(c)(3)","(c)(1)","(c)(4)"],"stext":{"head":"§1367. Supplemental jurisdiction","paras":[[0,"(a) Except as provided in subsections (b) and (c) or as expressly provided otherwise by Federal statute, in any civil action of which the district courts have original jurisdiction, the district courts shall have supplemental jurisdiction over all other claims that are so related to claims in the action within such original jurisdiction that they form part of the same case or controversy under Article III of the United States Constitution. Such supplemental jurisdiction shall include claims that involve the joinder or intervention of additional parties."],[0,"(b) In any civil action of which the district courts have original jurisdiction founded solely on section 1332 of this title, the district courts shall not have supplemental jurisdiction under subsection (a) over claims by plaintiffs against persons made parties under Rule 14, 19, 20, or 24 of the Federal Rules of Civil Procedure, or over claims by persons proposed to be joined as plaintiffs under Rule 19 of such rules, or seeking to intervene as plaintiffs under Rule 24 of such rules, when exercising supplemental jurisdiction over such claims would be inconsistent with the jurisdictional requirements of section 1332."],[0,"(c) The district courts may decline to exercise supplemental jurisdiction over a claim under subsection (a) if—"],[1,"(1) the claim raises a novel or complex issue of State law,"],[1,"(2) the claim substantially predominates over the claim or claims over which the district court has original jurisdiction,"],[1,"(3) the district court has dismissed all claims over which it has original jurisdiction, or"],[1,"(4) in exceptional circumstances, there are other compelling reasons for declining jurisdiction."],[0,"(d) The period of limitations for any claim asserted under subsection (a), and for any other claim in the same action that is voluntarily dismissed at the same time as or after the dismissal of the claim under subsection (a), shall be tolled while the claim is pending and for a period of 30 days after it is dismissed unless State law provides for a longer tolling period."],[0,"(e) As used in this section, the term \"State\" includes the District of Columbia, the Commonwealth of Puerto Rico, and any territory or possession of the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1367?type=usc&year=mostrecent&link-type=html"},"by":{"0":"2, 3, 2, 11, 16, 23, 25, 12, 24, 46, 16, 26, 26, 12, 14, 26, 39","1":"8, 10, 32, 37, 38, 8, 10, 32, 37, 38, 11, 38, 41","2":"2, 4-6, 10, 11, 8, 14, 14, 2, 8, 14, 14, 15"},"q":[{"src":"brief","b":0,"text":"the district courts shall have supplemental jurisdiction over all other claims that are so related to claims in the action within [their] original jurisdiction that they form part of the same case or controversy.","cite":"28 U.S.C. § 1367(a)"},{"src":"brief","b":0,"text":"original jurisdiction that they form part of the same case or controversy.","cite":"28 U.S.C. § 1367(a)"},{"src":"brief","b":1,"text":"civil action of which the district courts have original jurisdiction,","cite":"28 U.S.C. § 1367(a)"},{"src":"brief","b":1,"text":"which the district courts have original jurisdiction.","cite":"28 U.S.C. § 1367(a)"},{"src":"brief","b":2,"text":"expressly provided otherwise by Federal statute.","cite":"28 U.S.C. § 1367(a)"},{"src":"brief","b":2,"text":"the district courts shall have supplemental jurisdiction over all other claims,","cite":"28 U.S.C. § 1367(a)"},{"src":"argument","who":"Ms. Wellington","text":"It conflicts with the text and structure of Section 1367 with more than a century of precedent. Chief Justice Marshall held in Mollan against Torrance in 1824 that in a diversity case, a federal court's jurisdiction once vested cannot be divested by subsequent events."},{"src":"argument","who":"Justice Thomas","text":"You mentioned Section 1367. Could you spend a few minutes on your argument as to how it disposes of -- supports your argument?"},{"src":"argument","who":"Ms. Wellington","text":"So the text of Section 1367 states that there is supplemental jurisdiction unless Congress has expressly provided otherwise. And the text of Section 1367 does not say that when a plaintiff amends the complaint to delete the federal question, there is no longer supplemental jurisdiction."}]},{"t":"usc","label":"28 U.S.C. § 1441","url":"https://www.law.cornell.edu/uscode/text/28/1441","subs":["(a)"],"by":{"0":"3, 24, 36, 37"}},{"t":"usc","label":"28 U.S.C. § 1446","url":"https://www.law.cornell.edu/uscode/text/28/1446","subs":["(b)(3)","(c)(2)"],"stext":{"head":"§1446. Procedure for removal of civil actions","paras":[[0,"(a) Generally.—A defendant or defendants desiring to remove any civil action from a State court shall file in the district court of the United States for the district and division within which such action is pending a notice of removal signed pursuant to Rule 11 of the Federal Rules of Civil Procedure and containing a short and plain statement of the grounds for removal, together with a copy of all process, pleadings, and orders served upon such defendant or defendants in such action."],[0,"(b) Requirements; Generally.—(1) The notice of removal of a civil action or proceeding shall be filed within 30 days after the receipt by the defendant, through service or otherwise, of a copy of the initial pleading setting forth the claim for relief upon which such action or proceeding is based, or within 30 days after the service of summons upon the defendant if such initial pleading has then been filed in court and is not required to be served on the defendant, whichever period is shorter."],[0,"(2)(A) When a civil action is removed solely under section 1441(a), all defendants who have been properly joined and served must join in or consent to the removal of the action."],[0,"(B) Each defendant shall have 30 days after receipt by or service on that defendant of the initial pleading or summons described in paragraph (1) to file the notice of removal."],[0,"(C) If defendants are served at different times, and a later-served defendant files a notice of removal, any earlier-served defendant may consent to the removal even though that earlier-served defendant did not previously initiate or consent to removal."],[0,"(3) Except as provided in subsection (c), if the case stated by the initial pleading is not removable, a notice of removal may be filed within thirty days after receipt by the defendant, through service or otherwise, of a copy of an amended pleading, motion, order or other paper from which it may first be ascertained that the case is one which is or has become removable."],[0,"(c) Requirements; Removal Based on Diversity of Citizenship.—(1) A case may not be removed under subsection (b)(3) on the basis of jurisdiction conferred by section 1332 more than 1 year after commencement of the action, unless the district court finds that the plaintiff has acted in bad faith in order to prevent a defendant from removing the action."],[0,"(2) If removal of a civil action is sought on the basis of the jurisdiction conferred by section 1332(a), the sum demanded in good faith in the initial pleading shall be deemed to be the amount in controversy, except that—"],[1,"(A) the notice of removal may assert the amount in controversy if the initial pleading seeks—"],[2,"(i) nonmonetary relief; or"],[2,"(ii) a money judgment, but the State practice either does not permit demand for a specific sum or permits recovery of damages in excess of the amount demanded; and"],[1,"(B) removal of the action is proper on the basis of an amount in controversy asserted under subparagraph (A) if the district court finds, by the preponderance of the evidence, that the amount in controversy exceeds the amount specified in section 1332(a)."],[0,"(3)(A) If the case stated by the initial pleading is not removable solely because the amount in controversy does not exceed the amount specified in section 1332(a), information relating to the amount in controversy in the record of the State proceeding, or in responses to discovery, shall be treated as an \"other paper\" under subsection (b)(3)."],[0,"(B) If the notice of removal is filed more than 1 year after commencement of the action and the district court finds that the plaintiff deliberately failed to disclose the actual amount in controversy to prevent removal, that finding shall be deemed bad faith under paragraph (1)."],[0,"(d) Notice to Adverse Parties and State Court.—Promptly after the filing of such notice of removal of a civil action the defendant or defendants shall give written notice thereof to all adverse parties and shall file a copy of the notice with the clerk of such State court, which shall effect the removal and the State court shall proceed no further unless and until the case is remanded."],[0,"(e) Counterclaim in 337 Proceeding.—With respect to any counterclaim removed to a district court pursuant to section 337(c) of the Tariff Act of 1930, the district court shall resolve such counterclaim in the same manner as an original complaint under the Federal Rules of Civil Procedure, except that the payment of a filing fee shall not be required in such cases and the counterclaim shall relate back to the date of the original complaint in the proceeding before the International Trade Commission under section 337 of that Act."],[0,"(g) 1 Where the civil action or criminal prosecution that is removable under section 1442(a) is a proceeding in which a judicial order for testimony or documents is sought or issued or sought to be enforced, the 30-day requirement of subsection (b) of this section and paragraph (1) of section 1455(b) is satisfied if the person or entity desiring to remove the proceeding files the notice of removal not later than 30 days after receiving, through service, notice of any such proceeding."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1446?type=usc&year=mostrecent&link-type=html"},"by":{"0":"3, 36","1":"10, 33, 37","2":"11, 11"},"q":[{"src":"brief","b":1,"text":"the sum demanded in good faith in the initial pleading shall be deemed to be the amount in controversy.","cite":"28 U.S.C. § 1446(c)(2)"}]},{"t":"usc","label":"28 U.S.C. § 1447","url":"https://www.law.cornell.edu/uscode/text/28/1447","subs":["(c)","(c)(1982)","(d)","(e)"],"stext":{"head":"§1447. Procedure after removal generally","paras":[[0,"(a) In any case removed from a State court, the district court may issue all necessary orders and process to bring before it all proper parties whether served by process issued by the State court or otherwise."],[0,"(b) It may require the removing party to file with its clerk copies of all records and proceedings in such State court or may cause the same to be brought before it by writ of certiorari issued to such State court."],[0,"(c) A motion to remand the case on the basis of any defect other than lack of subject matter jurisdiction must be made within 30 days after the filing of the notice of removal under section 1446(a). If at any time before final judgment it appears that the district court lacks subject matter jurisdiction, the case shall be remanded. An order remanding the case may require payment of just costs and any actual expenses, including attorney fees, incurred as a result of the removal. A certified copy of the order of remand shall be mailed by the clerk to the clerk of the State court. The State court may thereupon proceed with such case."],[0,"(d) An order remanding a case to the State court from which it was removed is not reviewable on appeal or otherwise, except that an order remanding a case to the State court from which it was removed pursuant to section 1442 or 1443 of this title shall be reviewable by appeal or otherwise."],[0,"(e) If after removal the plaintiff seeks to join additional defendants whose joinder would destroy subject matter jurisdiction, the court may deny joinder, or permit joinder and remand the action to the State court."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1447?type=usc&year=mostrecent&link-type=html"},"by":{"0":"3, 39, 14, 39, 40, 40, 48, 46","1":"36","2":"8"},"q":[{"src":"brief","b":0,"text":"[i]f at any time before final judgment it appears that the district court lacks subject matter jurisdiction, the case shall be remanded.","cite":"28 U.S.C. § 1447(c)"},{"src":"brief","b":0,"text":"motion to remand the case on the basis of any defect other than lack of subject matter jurisdiction must be made within 30 days after the filing of the notice of removal.","cite":"28 U.S.C. § 1447(c)"},{"src":"brief","b":1,"text":"the court may deny joinder, or permit joinder and remand the action to the State court.","cite":"28 U.S.C. § 1447(e)"},{"src":"argument","who":"Ms. Wellington","text":"And this Court, in the Wisconsin Department of Corrections case, said that Section 1447 was merely procedural. It did not affect the district court's jurisdiction."}]},{"t":"law","label":"Judicial Improvements, Pub. L. No. 102-198","url":"https://www.govinfo.gov/link/statute/105/1623","by":{"0":"42"}},{"t":"law","label":"Pub. L. No. 112-51","url":"https://www.govinfo.gov/link/plaw/112/public/51","by":{"0":"41"}},{"t":"law","label":"United States District Court: Removal Proce- dure, Pub. L. No. 104-219","url":"https://www.govinfo.gov/link/plaw/104/public/219","by":{"0":"41, 42"}},{"t":"rule","label":"Fed. R. Civ. P. 15","url":"https://www.law.cornell.edu/rules/frcp/rule_15","subs":["(a)","(a)(2)","(c)"],"by":{"0":"47, 48","1":"45, 7, 35, 43, 8, 10, 35"},"q":[{"src":"brief","b":1,"text":"amendment to a pleading relates back to the date of the original pleading.","cite":"Fed. R. Civ. P. 15(a)"}]},{"t":"case","label":"Almond v. Capital Props.","cite":"212 F.3d 20","y":2000,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/212/20/","by":{"1":"19"}},{"t":"case","label":"Am. Car & Foundry Co. v. Kettelhake","cite":"236 U.S. 311","y":1915,"id":"scdb/1914-219","sc":1,"by":{"1":"40"}},{"t":"case","label":"Am. Well Works Co. v. Layne & Bowler Co.","cite":"241 U.S. 257","y":1916,"id":"scdb/1915-189","sc":1,"by":{"1":"2, 3, 14, 29"},"q":[{"src":"brief","b":1,"text":"A suit arises under the law that creates the cause of action.","cite":"241 U.S. 257, 260"},{"src":"argument","who":"Ms. Wellington","text":"We've cited other cases where it's been pending in federal court for a long time and right before an adverse decision -- so that's on page 16 of our yellow brief -- right before an adverse decision, the plaintiff amends their complaint to try to get back to state court. And in that situation, district courts have said: Well, I'm going to balance this attempt at gamesmanship with other considerations like --"},{"src":"argument","who":"Chief Justice Roberts","text":"Well, the original complaint but not the removed complaint. In other words, not the complaint with all the federal things stripped out of it."},{"src":"argument","who":"Justice Alito","text":"Yeah. Well, why should there be a different rule regarding parties and claims?"}]},{"t":"case","label":"Arrington v. City of Raleigh","cite":"369 F. App’x 420","y":2010,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/369/420/","by":{"1":"45"}},{"t":"case","label":"Bailey v. Johnson","cite":"48 F.3d 965","y":1995,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/48/965/","by":{"1":"22-23"}},{"t":"case","label":"Burrell v. Bayer Corp.","cite":"918 F.3d 372","y":2019,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/918/372/","by":{"1":"22, 23"}},{"t":"case","label":"Carr v. United States","cite":"560 U.S. 438","y":2010,"id":"2009/08-1301","sc":1,"by":{"1":"33"},"q":[{"src":"brief","b":1,"text":"[T]he present tense generally does not include the past.","cite":"560 U.S. 438, 448"}]},{"t":"case","label":"Caterpillar Inc. v. Williams","cite":"482 U.S. 386","y":1987,"id":"1986/86-526","sc":1,"by":{"1":"34, 46","2":"23"},"q":[{"src":"brief","b":1,"text":"plaintiff [is] the master of the claim; he or she may avoid federal jurisdiction by exclusive reliance on state law.","cite":"482 U.S. 386, 392"},{"src":"brief","b":1,"text":"may avoid federal jurisdiction by exclusive reliance on state law.","cite":"482 U.S. at 392"}]},{"t":"case","label":"Christianson v. Colt Indus. Operating Corp.","cite":"486 U.S. 800","y":1988,"id":"1987/87-499","sc":1,"by":{"1":"23-25"},"q":[{"src":"brief","b":1,"text":"claim supported by alternative theories in the complaint may not form the basis for [federal question] jurisdiction unless [federal] law is essential to each of those theories.","cite":"486 U.S. at 810"}]},{"t":"case","label":"Clark v. Velsicol Chem. Corp.","cite":"944 F.2d 196","y":1991,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/944/196/","by":{"1":"23"}},{"t":"case","label":"Dirauf v. Berger","cite":"57 F.4th 101","y":2022,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.4th/57/101/","by":{"1":"44"}},{"t":"case","label":"Direct Mktg. Ass’n v. Brohl","cite":"575 U.S. 1","y":2015,"id":"2014/13-1032","sc":1,"by":{"1":"18"}},{"t":"case","label":"Empire Healthchoice Assurance, Inc. v. McVeigh","cite":"547 U.S. 677","y":2006,"id":"2005/05-200","sc":1,"by":{"1":"17"}},{"t":"case","label":"Enochs v. Lampasas Cnty.","cite":"641 F.3d 155","y":2011,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/641/155/","by":{"1":"45"}},{"t":"case","label":"Ford Motor Co. v. Mont. Eighth Jud. Dist. Ct.","cite":"592 U.S. 351","y":2021,"url":"https://supreme.justia.com/cases/federal/us/592/351/","sc":1,"by":{"1":"42"}},{"t":"case","label":"Franchise Tax Bd. of Cal. v. Constr. Laborers Vacation Trust","cite":"463 U.S. 1","y":1983,"id":"1982/82-695","sc":1,"by":{"1":"24","2":"18, 23"},"q":[{"src":"brief","b":1,"text":"Since there are ‘reasons completely unrelated to the provisions and purposes’ of federal patent law why petitioners ‘may or may not be entitled to the relief [they] see[k]’ under their monopolization claim, the claim does not ‘arise under’ federal patent law.","cite":"463 U.S. at 26"},{"src":"brief","b":2,"text":"as permitting Congress to extend federal jurisdiction to any case of which federal law potentially ‘forms an ingredient.’","cite":"463 U.S. 1, 8 n.8"}]},{"t":"case","label":"Gamel v. City of Cincinnati","cite":"625 F.3d 949","y":2010,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/625/949/","by":{"1":"45"}},{"t":"case","label":"Gen. Inv. Co. v. Lake Shore & Mich. S. Ry. Co.","cite":"260 U.S. 261","y":1922,"id":"scdb/1922-037","sc":1,"by":{"1":"39"},"q":[{"src":"brief","b":1,"text":"subject to reconsideration, and would continue to be so up to the passing of a final decree.","cite":"260 U.S. 261, 267"}]},{"t":"case","label":"Grable & Sons Metal Prods., Inc. v. Darue Eng’g & Mfg.","cite":"545 U.S. 308","y":2005,"id":"2004/04-603","sc":1,"by":{"1":"34","2":"1, 3, 17-25"},"q":[{"src":"brief","b":1,"text":"a federal forum may entertain a state law claim implicating a disputed and substantial federal issue ‘without disturbing any congressionally approved balance of federal and state judicial responsibilities.’","cite":"545 U.S. at 314"},{"src":"brief","b":1,"text":"combination of no federal cause of action and no preemption of state remedies for misbranding.","cite":"545 U.S. at 318"},{"src":"brief","b":2,"text":"congressionally approved balance of federal and state judicial responsibilities.","cite":"545 U.S. at 314"},{"src":"brief","b":2,"text":"violation of federal statutes and regulations is commonly given negligence per se effect in state tort proceedings.","cite":"545 U.S. at 318"},{"src":"argument","who":"Ms. Wellington","text":"Respondents realize how weak their case is and instead ask the Court to decide something else, whether Grable should be overruled and, if not, whether Grable's requirements were met."},{"src":"argument","who":"Chief Justice Roberts","text":"Your -- your briefing, obviously, suggests at least at the outset you don't think Grable has much to do with this case. And your friend on the other side obviously disagrees."},{"src":"argument","who":"Ms. Wellington","text":"We agree that there has to be an adjudication of the Grable question in order to get to the ultimate, you know, remedy in this case. But that's not what we're asking this Court to decide."}]},{"t":"case","label":"Gully v. First Nat’l Bank","cite":"299 U.S. 109","y":1936,"id":"scdb/1936-005","sc":1,"by":{"1":"15-17"}},{"t":"case","label":"Hartland Lakeside Joint No. 3 Sch. Dist. v. WEA Ins. Corp.","cite":"756 F.3d 1032","y":2014,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/756/1032/","by":{"1":"19"}},{"t":"case","label":"Hertz Corp. v. Friend","cite":"559 U.S. 77","y":2010,"id":"2009/08-1107","sc":1,"by":{"1":"18, 19"},"q":[{"src":"brief","b":1,"text":"complicate a case, eating up time and money as the parties litigate, not the merits of their claims, but which court is the right court to decide those claims.","cite":"559 U.S. 77, 94"}]},{"t":"case","label":"Hopkins v. Walker","cite":"244 U.S. 486","y":1917,"id":"scdb/1916-106","sc":1,"by":{"1":"21"}},{"t":"case","label":"Janus v. Am. Fed’n of State, Cnty., & Mun. Emps., Council 31","cite":"585 U.S. 878","y":2018,"url":"https://supreme.justia.com/cases/federal/us/585/878/","sc":1,"by":{"1":"29"}},{"t":"case","label":"Jones v. R.R. Donnelley & Sons Co.","cite":"541 U.S. 369","y":2004,"id":"2003/02-1205","sc":1,"by":{"1":"12"},"q":[{"src":"brief","b":1,"text":"‘come into being; originate’ or ‘spring up.’","cite":"541 U.S. 369, 382-83"}]},{"t":"case","label":"Knick v. Township of Scott, Pennsylvania","cite":"588 U.S. 180","y":2019,"id":"2018/17-647","sc":1,"by":{"1":"29, 30"},"q":[{"src":"brief","b":1,"text":"identified several factors to consider in deciding whether to overrule a past decision, including ‘the quality of [its] reasoning, the workability of the rule it established, its consistency with other related decisions, . . . and reliance on the decision.","cite":"588 U.S. 180, 203"},{"src":"brief","b":1,"text":"as a guide to lawful behavior.","cite":"588 U.S. at 205"}]},{"t":"case","label":"Krupski v. Costa Crociere S.p.A.","cite":"560 U.S. 538","y":2010,"id":"2009/09-337","sc":1,"by":{"1":"35"},"q":[{"src":"brief","b":1,"text":"mandates relation back . . . it does not leave the decision . . . to the district court’s equitable discretion.","cite":"560 U.S. 538, 553"}]},{"t":"case","label":"Loper Bright Enters. v. Raimondo","cite":"144 S. Ct. 2244","y":2024,"id":"2023/22-451","sc":1,"by":{"1":"29, 30, 42, 46"},"q":[{"src":"brief","b":1,"text":"if it was ever coherent enough to be called a rule at all.","cite":"144 S. Ct. 2244, 2270"},{"src":"brief","b":1,"text":"it would be a mistake to read judicial opinions like statutes,","cite":"144 S. Ct. at 2281"}]},{"t":"case","label":"Louisville & Nashville R.R. Co. v. W. Union Tel. Co.","cite":"237 U.S. 300","y":1915,"id":"scdb/1914-086","sc":1,"by":{"1":"14, 15, 29"},"q":[{"src":"brief","b":1,"text":"[t]he state law is the sole determinant of the conditions supposed, and its reference elsewhere for their fulfilment is like the reference to a document that it adopts and makes part of itself. The suit is not maintained by virtue of the Act of Congress, but by virtue of the Louisiana statute that allows itself to be satisfied by that act.","cite":"237 U.S. 300, 303"}]},{"t":"case","label":"Merrell Dow Pharms. Inc. v. Thompson","cite":"478 U.S. 804","y":1986,"id":"1985/85-619","sc":1,"by":{"1":"22, 23, 25, 27, 30","2":"24"},"q":[{"src":"brief","b":1,"text":"the mere presence of a federal issue in a state cause of action does not automatically confer federalquestion jurisdiction.","cite":"478 U.S. at 813"},{"src":"brief","b":1,"text":"[t]he novelty of an FDCA issue is not sufficient to give it status as a federal cause of action; nor should it be sufficient to give a state-based FDCA claim status as a jurisdiction-triggering federal question.","cite":"478 U.S. at 817"},{"src":"argument","who":"Mr. Keller","text":"This case is Merrell Dow but for pets not people. And while I take a back seat to nobody in my love of our four-legged friends, I am confident Congress believed that misbranded human product was a more substantial federal issue than misbranded pet food."},{"src":"argument","who":"Mr. Keller","text":"Of course. And then I win under Grable or Merrell Dow."}]},{"t":"case","label":"Merrill Lynch, Pierce, Fenner & Smith Inc. v. Manning","cite":"578 U.S. 374","y":2016,"id":"2015/14-1132","sc":1,"by":{"1":"43","2":"19, 21"},"q":[{"src":"brief","b":1,"text":"that a judge should go behind the face of a complaint to determine whether it is the product of ‘artful pleading.’","cite":"578 U.S. 374, 392-93"}]},{"t":"case","label":"Miller’s Executors v. Swann","cite":"150 U.S. 132","y":1893,"id":"scdb/1893-024","sc":1,"by":{"1":"12, 13, 15, 29"}},{"t":"case","label":"Moore v. Chesapeake & Ohio Ry. Co.","cite":"291 U.S. 205","y":1934,"id":"scdb/1933-077","sc":1,"by":{"1":"16, 17"}},{"t":"case","label":"Pac. Bell Tel. Co. v. linkLine Commc’ns, Inc.","cite":"555 U.S. 438","y":2009,"id":"2008/07-512","sc":1,"by":{"1":"35"}},{"t":"case","label":"Packard v. Farmers Ins. Co. of Columbus Inc.","cite":"423 F. App’x 580","y":2011,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/423/580/","by":{"1":"44"}},{"t":"case","label":"Pan Am. Petroleum Corp. v. Super. Ct.","cite":"366 U.S. 656","y":1961,"id":"1960/80","sc":1,"by":{"1":"34"},"q":[{"src":"brief","b":1,"text":"[T]he complaints . . . determine the nature of the suits,","cite":"366 U.S. 656, 662-63"}]},{"t":"case","label":"Pollock v. Farmers’ Loan & Trust Co.","cite":"157 U.S. 429","y":1895,"id":"1850-1900/157us429","sc":1,"by":{"1":"16"}},{"t":"case","label":"Sisson v. Ruby","cite":"497 U.S. 358","y":1990,"id":"1989/88-2041","sc":1,"by":{"1":"21"},"q":[{"src":"brief","b":1,"text":"produce[s] the sort of vague boundary that is to be avoided in the area of subject-matter jurisdiction wherever possible.","cite":"497 U.S. 358, 37475"}]},{"t":"case","label":"Smith v. Kansas City Title & Trust Co.","cite":"255 U.S. 180","y":1921,"id":"scdb/1920-177","sc":1,"by":{"1":"9, 15-17, 21, 29, 30"},"q":[{"src":"brief","b":1,"text":"If the Missouri law authorizes or forbids the investment according to the determination of this Court upon a point under the Constitution or Acts of Congress, still that point is material only because the Missouri law saw fit to make it so. The whole foundation of the duty is Missouri law, which at its sole will incorporated the other law as it might incorporate a document. The other law or document depends for its relevance and effect not on its own force but upon the law that took it up, so I repeat once more the cause of action arises wholly from the law of the State. . . . [S]o it has been decided by this Court again and again.","cite":"255 U.S. at 214"}]},{"t":"case","label":"South Dakota v. Wayfair","cite":"585 U.S. 162","y":2018,"id":"2017/17-494","sc":1,"by":{"1":"30"},"q":[{"src":"brief","b":1,"text":"clear or easily applicable standard, so arguments for reliance based on its clarity are misplaced.","cite":"585 U.S. 162, 186"}]},{"t":"case","label":"Syngenta Crop Protec., Inc. v. Henson","cite":"537 U.S. 28","y":2002,"id":"2002/01-757","sc":1,"by":{"1":"46"},"q":[{"src":"brief","b":1,"text":"statutory procedures for removal are to be strictly construed.","cite":"537 U.S. 28, 32"}]},{"t":"case","label":"Universal Health Servs., Inc. v. United States","cite":"579 U.S. 176","y":2016,"id":"2015/15-7","sc":1,"by":{"1":"42"},"q":[{"src":"brief","b":1,"text":"policy arguments cannot supersede the clear statutory text.","cite":"579 U.S. 176, 192"}]},{"t":"case","label":"Van Buren v. United States","cite":"593 U.S. 374","y":2021,"id":"2020/19-783","sc":1,"by":{"1":"31"}},{"t":"case","label":"Watson v. City of Allen","cite":"821 F.3d 634","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/821/634/","by":{"1":"44"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"1":"32"}},{"t":"const","label":"Article VI, Clause 2","clauses":[["supremacy","Supremacy Clause"]],"text":"This Constitution, and the Laws of the United States which shall be made in Pursuance thereof; and all Treaties made, or which shall be made, under the Authority of the United States, shall be the supreme Law of the Land; and the Judges in every State shall be bound thereby, any Thing in the Constitution or Laws of any State to the Contrary notwithstanding.","by":{"1":"14"}},{"t":"usc","label":"28 U.S.C. § 1257","url":"https://www.law.cornell.edu/uscode/text/28/1257","by":{"1":"15"}},{"t":"usc","label":"28 U.S.C. § 1453","url":"https://www.law.cornell.edu/uscode/text/28/1453","subs":["(c)"],"by":{"1":"5"}},{"t":"rule","label":"Fed. R. Civ. P. 3","url":"https://www.law.cornell.edu/rules/frcp/rule_3","by":{"1":"34","2":"6"}},{"t":"rule","label":"Fed. R. Civ. P. 12","url":"https://www.law.cornell.edu/rules/frcp/rule_12","subs":["(b)(6)"],"by":{"1":"7, 39"}},{"t":"rule","label":"Fed. R. Civ. P. 41","url":"https://www.law.cornell.edu/rules/frcp/rule_41","by":{"1":"11, 43"}},{"t":"rule","label":"Fed. R. Civ. P. 54","url":"https://www.law.cornell.edu/rules/frcp/rule_54","subs":["(b)","(c)"],"by":{"1":"39, 25","2":"24"},"q":[{"src":"brief","b":1,"text":"grant the relief to which each party is entitled, even if the party has not demanded that relief in its pleadings.","cite":"Fed. R. Civ. P. 54(c)"},{"src":"brief","b":2,"text":"should grant the relief to which each party is entitled, even if the party has not demanded that relief.","cite":"Fed. R. Civ. P. 54(c)"}]},{"t":"rule","label":"Fed. R. Civ. P. 81","url":"https://www.law.cornell.edu/rules/frcp/rule_81","subs":["(c)(2)"],"by":{"1":"34"}},{"t":"case","label":"Am. Fiber & Finishing, Inc. v. Tyco Healthcare Grp., LP","cite":"362 F.3d 136","y":2004,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/362/136/","by":{"2":"8"}},{"t":"case","label":"Bell v. Hood","cite":"327 U.S. 678","y":1946,"id":"scdb/1945-042","sc":1,"by":{"2":"23"}},{"t":"case","label":"Beneficial Nat’l Bank v. Anderson","cite":"539 U.S. 1","y":2003,"id":"2002/02-306","sc":1,"by":{"2":"23"},"q":[{"src":"brief","b":2,"text":"an exclusive federal cause of action.","cite":"539 U.S. 1, 10"}]},{"t":"case","label":"BP P.L.C. v. Mayor & City Council of Baltimore","cite":"141 S. Ct. 1532","y":2021,"id":"2020/19-1189","sc":1,"by":{"2":"20"}},{"t":"case","label":"Broadway Grill, Inc. v. Visa Inc.","cite":"856 F.3d 1274","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/856/1274/","by":{"2":"9"}},{"t":"case","label":"Federated Dep’t Stores, Inc. v. Moitie","cite":"452 U.S. 394","y":1981,"id":"1980/79-1517","sc":1,"by":{"2":"20"},"q":[{"src":"brief","b":2,"text":"settled principle to the facts of this case,","cite":"452 U.S. 394, 397 n.2"}]},{"t":"case","label":"Freeport-McMoRan, Inc. v. K N Energy, Inc.","cite":"498 U.S. 426","y":1991,"id":"1990/90-655","sc":1,"by":{"2":"7-9"}},{"t":"case","label":"Grispino v. New England Mut. Life Ins. Co.","cite":"358 F.3d 16","y":2004,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/358/16/","by":{"2":"17"}},{"t":"case","label":"Grupo Dataflux v. Atlas Glob. Grp., L.P.","cite":"541 U.S. 567","y":2004,"id":"2003/02-1689","sc":1,"by":{"2":"7"}},{"t":"case","label":"Jones v. Houston Indep. Sch. Dist.","cite":"979 F.2d 1004","y":1992,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/979/1004/","by":{"2":"17"}},{"t":"case","label":"Kimble v. Marvel Ent., LLC","cite":"576 U.S. 446","y":2015,"id":"2014/13-720","sc":1,"by":{"2":"19"}},{"t":"case","label":"Kucana v. Holder","cite":"558 U.S. 233","y":2010,"id":"2009/08-911","sc":1,"by":{"2":"10"},"q":[{"src":"brief","b":2,"text":"‘leave[s] the matter where it was pre-codification’","cite":"558 U.S. 233, 250"}]},{"t":"case","label":"Lucente v. Int’l Bus. Machines Corp.","cite":"310 F.3d 243","y":2002,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/310/243/","by":{"2":"9"},"q":[{"src":"argument","who":"Ms. Wellington","text":"We cited the Lucente case in the Second Circuit that reinstates the original complaint on appeal. So, if that's the test, we think that's met."}]},{"t":"case","label":"Mendoza v. Murphy","cite":"532 F.3d 342","y":2008,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/532/342/","by":{"2":"16"}},{"t":"case","label":"Metro. Life Ins. Co. v. Taylor","cite":"481 U.S. 58","y":1987,"id":"1986/85-686","sc":1,"by":{"2":"23"}},{"t":"case","label":"New Mexico v. Gen. Elec. Co.","cite":"467 F.3d 1223","y":2006,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/467/1223/","by":{"2":"16"}},{"t":"case","label":"Ortolf v. Silver Bar Mines, Inc.","cite":"111 F.3d 85","y":1997,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/111/85/","by":{"2":"6"},"q":[{"src":"brief","b":2,"text":"require that supplemental jurisdiction be exercised in the same case, not a separate or subsequent case.","cite":"111 F.3d 85, 87"}]},{"t":"case","label":"Owen Equip. & Erection Co. v. Kroger","cite":"437 U.S. 365","y":1978,"id":"1977/77-677","sc":1,"by":{"2":"9"},"q":[{"src":"brief","b":2,"text":"do not create or withdraw federal jurisdiction,","cite":"437 U.S. 365, 370"},{"src":"argument","who":"Justice Kavanaugh","text":"Like Morgan's Heirs and St. Paul Mercury on the one hand and Owen Equipment on the other, there's no logic connecting those things at least as I see it."}]},{"t":"case","label":"S. Cent. Bell Tel. Co. v. Alabama","cite":"526 U.S. 160","y":1999,"id":"1998/97-2045","sc":1,"by":{"2":"18"}},{"t":"case","label":"Sinochem Int’l Co. v. Malaysia Int’l Shipping Corp.","cite":"549 U.S. 422","y":2007,"id":"2006/06-102","sc":1,"by":{"2":"20"},"q":[{"src":"argument","who":"Ms. Wellington","text":"That's what it held in Sinochem. We agree that there has to be an adjudication of the Grable question in order to get to the ultimate, you know, remedy in this case."}]},{"t":"case","label":"T. B. Harms Co. v. Eliscu","cite":"339 F.2d 823","y":1964,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/339/823/","by":{"2":"19"},"q":[{"src":"brief","b":2,"text":"more useful for inclusion than for the exclusion for which it was intended.","cite":"339 F.2d 823, 827"}]},{"t":"case","label":"Verlinden B.V. v. Central Bank of Nigeria","cite":"461 U.S. 480","y":1983,"id":"1982/81-920","sc":1,"by":{"2":"7"}},{"t":"case","label":"Williams v. Newark Beth Israel Med. Ctr.","cite":"322 F. App’x 111","y":2009,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/322/111/","by":{"2":"16"}},{"t":"usc","label":"1 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/1/1","stext":{"head":"§1. Words denoting number, gender, and so forth","paras":[[0,"In determining the meaning of any Act of Congress, unless the context indicates otherwise—"],[1,"words importing the singular include and apply to several persons, parties, or things;"],[1,"words importing the plural include the singular;"],[1,"words importing the masculine gender include the feminine as well;"],[1,"words used in the present tense include the future as well as the present;"],[1,"the words \"insane\" and \"insane person\" shall include every idiot, insane person, and person non compos mentis;"],[1,"the words \"person\" and \"whoever\" include corporations, companies, associations, firms, partnerships, societies, and joint stock companies, as well as individuals;"],[1,"\"officer\" includes any person authorized by law to perform the duties of the office;"],[1,"\"signature\" or \"subscription\" includes a mark when the person making the same intended it as such;"],[1,"\"oath\" includes affirmation, and \"sworn\" includes affirmed;"],[1,"\"writing\" includes printing and typewriting and reproductions of visual symbols by photographing, multigraphing, mimeographing, manifolding, or otherwise."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/1/1?type=usc&year=mostrecent&link-type=html"},"by":{"2":"6"},"q":[{"src":"brief","b":2,"text":"the present tense include[s] the future.","cite":"1 U.S.C. § 1"}]},{"t":"usc","label":"11 U.S.C. § 524","url":"https://www.law.cornell.edu/uscode/text/11/524","subs":["(a)(2)"],"by":{"2":"10"}},{"t":"usc","label":"21 U.S.C. § 337","url":"https://www.law.cornell.edu/uscode/text/21/337","subs":["(a)","(b)"],"by":{"2":"22, 23, 23"}},{"t":"rule","label":"Fed. R. Civ. P. 7","url":"https://www.law.cornell.edu/rules/frcp/rule_7","subs":["(a)(1)"],"by":{"2":"6"}},{"t":"rule","label":"Fed. R. Civ. P. 8","url":"https://www.law.cornell.edu/rules/frcp/rule_8","subs":["(a)(3)"],"by":{"2":"24"}}]};